package com.moviebooking.notification.service;
import com.moviebooking.notification.entity.Notification;import com.moviebooking.notification.enums.*;import com.moviebooking.notification.event.NotificationEvent;import com.moviebooking.notification.exception.*;import com.moviebooking.notification.repository.NotificationRepository;import com.moviebooking.notification.service.impl.NotificationServiceImpl;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import java.math.BigDecimal;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class NotificationServiceImplTest {@Mock NotificationRepository repo;@Mock EmailService email;@InjectMocks NotificationServiceImpl service;NotificationEvent event(){return NotificationEvent.builder().eventId("evt-1").userId("USR1").userEmail("u@example.com").bookingId("BK1").amount(BigDecimal.TEN).movieName("Movie").build();}@Test void bookingConfirmationIsStoredAndSent(){when(repo.existsByEventId("evt-1")).thenReturn(false);when(repo.save(any())).thenAnswer(i->{Notification n=i.getArgument(0);if(n.getId()==null)n.setId(1L);return n;});service.process(NotificationType.BOOKING_CONFIRMED,event());verify(email).send(any());verify(repo,times(2)).save(any());}@Test void paymentSuccessIsProcessed(){when(repo.existsByEventId(any())).thenReturn(false);when(repo.save(any())).thenAnswer(i->i.getArgument(0));service.process(NotificationType.PAYMENT_SUCCESS,event());verify(email).send(any());}@Test void paymentFailureIsProcessed(){when(repo.existsByEventId(any())).thenReturn(false);when(repo.save(any())).thenAnswer(i->i.getArgument(0));service.process(NotificationType.PAYMENT_FAILED,event());verify(email).send(any());}@Test void duplicateIsIgnored(){when(repo.existsByEventId("evt-1")).thenReturn(true);service.process(NotificationType.BOOKING_CONFIRMED,event());verifyNoInteractions(email);verify(repo,never()).save(any());}@Test void emailFailureMarksFailed(){when(repo.existsByEventId(any())).thenReturn(false);when(repo.save(any())).thenAnswer(i->i.getArgument(0));doThrow(new EmailDeliveryException("failed",new RuntimeException())).when(email).send(any());service.process(NotificationType.BOOKING_CONFIRMED,event());ArgumentCaptor<Notification> cap=ArgumentCaptor.forClass(Notification.class);verify(repo,times(2)).save(cap.capture());assertEquals(NotificationStatus.FAILED,cap.getAllValues().get(1).getStatus());}@Test void missingNotificationThrows(){when(repo.findById(9L)).thenReturn(Optional.empty());assertThrows(NotificationNotFoundException.class,()->service.one(9L));}}
